properties.query:
let exploit_events = SecurityEvent | where EventID == 4688 and NewProcessName has_any ("mshta.exe", "wmic.exe", "certutil.exe") | summarize exploit_time=min(TimeGenerated) by Computer;
let shell_events = SecurityEvent | where EventID == 4624 and LogonType == 10 | summarize shell_time=min(TimeGenerated) by Computer;
let propagation_events = NetworkEvents | where RemotePort in (445, 3389, 22, 135) | summarize prop_time=min(TimeGenerated), dest_count=dcount(DestinationIP) by SourceIP | where dest_count > 5;
exploit_events | join kind=inner shell_events on Computer | where shell_time - exploit_time between (0min .. 30min)
